const MANIFEST = {
  "type": "Diagrams.DecisionTreeNode",
  "description": "Interactive decision tree with collapsible branches, dynamic path highlighting, and hover-to-explore functionality",
  "editorElement": {
    "selector": ".decision-tree-container",
    "displayName": "Decision Tree Node",
    "archetype": "container",
    "data": {
      "rootQuestion": {
        "dataType": "text",
        "displayName": "Root Question",
        "defaultValue": "Should we proceed with this project?",
        "group": "Content"
      },
      "showPathHighlight": {
        "dataType": "booleanValue",
        "displayName": "Show Path Highlight",
        "defaultValue": true,
        "group": "Content"
      },
      "expandByDefault": {
        "dataType": "booleanValue",
        "displayName": "Expand All by Default",
        "defaultValue": false,
        "group": "Content"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "nodeBackgroundColor": {
        "dataType": "color",
        "displayName": "Node Background",
        "defaultValue": "#F8F9FA",
        "group": "Colors"
      },
      "nodeBorderColor": {
        "dataType": "color",
        "displayName": "Node Border",
        "defaultValue": "#E9ECEF",
        "group": "Colors"
      },
      "nodeTextColor": {
        "dataType": "color",
        "displayName": "Node Text Color",
        "defaultValue": "#212529",
        "group": "Colors"
      },
      "connectorColor": {
        "dataType": "color",
        "displayName": "Connector Color",
        "defaultValue": "#CED4DA",
        "group": "Colors"
      },
      "highlightColor": {
        "dataType": "color",
        "displayName": "Highlight Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "yesLabelColor": {
        "dataType": "color",
        "displayName": "Yes Label Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "noLabelColor": {
        "dataType": "color",
        "displayName": "No Label Color",
        "defaultValue": "#6C757D",
        "group": "Colors"
      },
      "nodeTextSize": {
        "dataType": "number",
        "displayName": "Node Text Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "nodeTextWeight": {
        "dataType": "select",
        "displayName": "Node Text Weight",
        "defaultValue": "400",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "labelTextSize": {
        "dataType": "number",
        "displayName": "Label Text Size (px)",
        "defaultValue": 12,
        "group": "Typography"
      },
      "labelTextWeight": {
        "dataType": "select",
        "displayName": "Label Text Weight",
        "defaultValue": "500",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "nodeCornerRadius": {
        "dataType": "select",
        "displayName": "Node Corner Radius",
        "defaultValue": "6px",
        "options": ["0px", "4px", "6px", "8px", "12px"],
        "group": "Layout"
      },
      "nodePadding": {
        "dataType": "select",
        "displayName": "Node Padding",
        "defaultValue": "16px",
        "options": ["12px", "16px", "20px", "24px"],
        "group": "Layout"
      },
      "branchSpacing": {
        "dataType": "select",
        "displayName": "Branch Spacing",
        "defaultValue": "60px",
        "options": ["40px", "60px", "80px", "100px"],
        "group": "Layout"
      },
      "connectorWidth": {
        "dataType": "select",
        "displayName": "Connector Width",
        "defaultValue": "2px",
        "options": ["1px", "2px", "3px"],
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'dt' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);
  const [expandedNodes, setExpandedNodes] = React.useState(new Set(['root']));
  const [hoveredPath, setHoveredPath] = React.useState(null);

  const rootQuestion = config?.rootQuestion || "Expand into the Lisbon market this quarter?";
  const showPathHighlight = bool(config?.showPathHighlight, true);
  const expandByDefault = bool(config?.expandByDefault, false);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const nodeBackgroundColor = config?.nodeBackgroundColor || "#F8F9FA";
  const nodeBorderColor = config?.nodeBorderColor || "#E9ECEF";
  const nodeTextColor = config?.nodeTextColor || "#212529";
  const connectorColor = config?.connectorColor || "#CED4DA";
  const highlightColor = config?.highlightColor || "#495057";
  const yesLabelColor = config?.yesLabelColor || "#495057";
  const noLabelColor = config?.noLabelColor || "#6C757D";
  const nodeTextSize = parseInt(config?.nodeTextSize || '14');
  const nodeTextWeight = config?.nodeTextWeight || "400";
  const labelTextSize = parseInt(config?.labelTextSize || '12');
  const labelTextWeight = config?.labelTextWeight || "500";
  const nodeCornerRadius = config?.nodeCornerRadius || "6px";
  const nodePadding = config?.nodePadding || "16px";
  const branchSpacing = parseInt(config?.branchSpacing || '60');
  const connectorWidth = config?.connectorWidth || "2px";

  const treeData = {
    id: 'root',
    text: rootQuestion,
    children: [
      {
        id: 'yes-1',
        branch: 'yes',
        text: 'Is the €2.4M budget approved?',
        children: [
          { id: 'yes-1-yes', branch: 'yes', text: 'Open the Lisbon office by Q3', terminal: true },
          { id: 'yes-1-no', branch: 'no', text: 'Escalate to the finance committee', terminal: true }
        ]
      },
      {
        id: 'no-1',
        branch: 'no',
        text: 'Is a distributor partnership available?',
        children: [
          { id: 'no-1-yes', branch: 'yes', text: 'Sign with a local distributor instead', terminal: true },
          { id: 'no-1-no', branch: 'no', text: 'Shelve expansion until next fiscal year', terminal: true }
        ]
      }
    ]
  };

  React.useEffect(() => {
    if (expandByDefault) {
      const allIds = new Set();
      const collectIds = (node) => {
        allIds.add(node.id);
        if (node.children) {
          node.children.forEach(collectIds);
        }
      };
      collectIds(treeData);
      setExpandedNodes(allIds);
    }
  }, [expandByDefault]);

  const toggleNode = (nodeId) => {
    setExpandedNodes(prev => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  };

  const renderNode = (node, depth = 0, parentPath = []) => {
    const isExpanded = expandedNodes.has(node.id);
    const hasChildren = node.children && node.children.length > 0;
    const currentPath = [...parentPath, node.id];
    const isHighlighted = showPathHighlight && hoveredPath && currentPath.every((id, i) => hoveredPath[i] === id);
    const isInteractive = hasChildren && !node.terminal;

    return (
      <div
        key={node.id}
        style={{
          marginLeft: depth > 0 ? branchSpacing + 'px' : '0',
          marginTop: depth > 0 ? '16px' : '0'
        }}
      >
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: '12px' }}>
          {depth > 0 && (
            <div style={{
              width: '24px',
              height: '24px',
              borderLeft: `${connectorWidth} solid ${isHighlighted ? highlightColor : connectorColor}`,
              borderBottom: `${connectorWidth} solid ${isHighlighted ? highlightColor : connectorColor}`,
              marginTop: '12px',
              transition: reduced ? 'none' : 'border-color 0.25s ease-out'
            }} />
          )}

          <div style={{ flex: 1 }}>
            {node.branch && (
              <div style={{
                fontSize: labelTextSize + 'px',
                fontWeight: labelTextWeight,
                color: node.branch === 'yes' ? yesLabelColor : noLabelColor,
                marginBottom: '4px',
                textTransform: 'uppercase',
                letterSpacing: '0.05em'
              }}>
                {node.branch}
              </div>
            )}

            <div
              className={`${p}-node`}
              role={isInteractive ? 'button' : undefined}
              tabIndex={isInteractive ? 0 : undefined}
              aria-expanded={isInteractive ? isExpanded : undefined}
              onMouseEnter={() => showPathHighlight && setHoveredPath(currentPath)}
              onMouseLeave={() => showPathHighlight && setHoveredPath(null)}
              onFocus={() => showPathHighlight && setHoveredPath(currentPath)}
              onBlur={() => showPathHighlight && setHoveredPath(null)}
              onClick={() => isInteractive && toggleNode(node.id)}
              onKeyDown={(e) => {
                if (isInteractive && (e.key === 'Enter' || e.key === ' ')) {
                  e.preventDefault();
                  toggleNode(node.id);
                }
              }}
              style={{
                backgroundColor: isHighlighted ? highlightColor : nodeBackgroundColor,
                border: `1px solid ${isHighlighted ? highlightColor : nodeBorderColor}`,
                borderRadius: nodeCornerRadius,
                padding: nodePadding,
                cursor: isInteractive ? 'pointer' : 'default',
                transition: reduced ? 'none' : 'all 0.25s ease-out',
                boxShadow: isHighlighted ? '0 2px 8px rgba(0,0,0,0.08)' : '0 1px 3px rgba(0,0,0,0.06)',
                color: isHighlighted ? '#FFFFFF' : nodeTextColor,
                fontSize: nodeTextSize + 'px',
                fontWeight: nodeTextWeight,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: '12px'
              }}
            >
              <span>{node.text}</span>
              {isInteractive && (
                <span style={{
                  fontSize: '12px',
                  opacity: 0.7,
                  transform: isExpanded ? 'rotate(180deg)' : 'rotate(0)',
                  transition: reduced ? 'none' : 'transform 0.25s ease-out'
                }}>
                  ▼
                </span>
              )}
            </div>

            {hasChildren && isExpanded && !node.terminal && (
              <div style={{
                marginTop: '8px',
                opacity: 1,
                animation: reduced ? 'none' : `${p}-fadeIn 0.4s ease-out`
              }}>
                {node.children.map(child => renderNode(child, depth + 1, currentPath))}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div
      className={`decision-tree-container ${p}`}
      style={{
        width: '100%',
        minHeight: '400px',
        backgroundColor,
        padding: '32px',
        position: 'relative'
      }}
    >
      <style>{`
        @keyframes ${p}-fadeIn {
          from {
            opacity: 0;
            transform: translateY(-10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .${p}-node:focus-visible {
          outline: 2px solid ${highlightColor};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>

      {renderNode(treeData)}
    </div>
  );
}

