          {hasReports && (
            <div style={{
              fontSize: '10px',
              opacity: 0.7,
              transform: isExpanded ? 'rotate(180deg)' : 'rotate(0)',
              transition: reduced ? 'none' : 'transform 0.25s ease-out',
              flexShrink: 0
            }}>
              ▼
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderNode = (person, depth = 0) => {
    const hasReports = person.reports && person.reports.length > 0;
    const isExpanded = expandedNodes.has(person.id);

    return (
      <div key={person.id} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        {renderCard(person, hasReports)}

        {hasReports && isExpanded && (
          <div style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            marginTop: levelSpacing + 'px',
            position: 'relative',
            opacity: 1,
            animation: reduced ? 'none' : `${p}-fadeIn 0.4s ease-out`
          }}>
            <div style={{
              width: '2px',
              height: (levelSpacing / 2) + 'px',
              backgroundColor: connectorColor,
              position: 'absolute',
              top: `-${levelSpacing}px`,
              left: '50%',
              transform: 'translateX(-50%)'
            }} />

            <div style={{
              display: 'flex',
              gap: siblingSpacing,
              justifyContent: 'center',
              position: 'relative'
            }}>
              {person.reports.length > 1 && (
                <div style={{
                  position: 'absolute',
                  top: `-${levelSpacing / 2}px`,
                  left: 0,
                  right: 0,
                  height: '2px',
                  backgroundColor: connectorColor
                }} />
              )}

              {person.reports.map((report, index) => (
                <div key={report.id} style={{ position: 'relative' }}>
                  <div style={{
                    width: '2px',
                    height: (levelSpacing / 2) + 'px',
                    backgroundColor: connectorColor,
                    position: 'absolute',
                    top: `-${levelSpacing / 2}px`,
                    left: '50%',
                    transform: 'translateX(-50%)'
                  }} />
                  {renderNode(report, depth + 1)}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div
      className={`org-chart-container ${p}`}
      style={{
        width: '100%',
        minHeight: '600px',
        backgroundColor,
        padding: '48px 24px',
        overflow: 'auto'
      }}
    >
      <style>{`
        @keyframes ${p}-fadeIn {
          from {
            opacity: 0;
            transform: translateY(-15px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .${p}-card:focus-visible {
          outline: 2px solid ${nameColor};
          outline-offset: 2px;
        }
