    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [text, childrenStr] = entry.split('|');
      const children = String(childrenStr || '').split(',').map((c) => c.trim()).filter(Boolean);
      return { id: i, text: (text || `Branch ${i + 1}`).trim(), children };
    });

  const branches = parsedBranches.length > 0 ? parsedBranches : defaultBranches;

  const [expandedBranches, setExpandedBranches] = React.useState(() => new Set(branches.map((b) => b.id)));

  const toggleBranch = (id) => {
    setExpandedBranches(prev => {
      const newSet = new Set(prev);
      newSet.has(id) ? newSet.delete(id) : newSet.add(id);
      return newSet;
    });
  };

  const getNodePosition = (index, total, distance) => {
    const angle = (360 / total) * index - 90;
    const rad = (angle * Math.PI) / 180;
    return {
      x: Math.cos(rad) * distance,
      y: Math.sin(rad) * distance
    };
  };

  return (
    <div className={`mindmap-container ${p}`} style={{ width: '100%', minHeight: '700px', backgroundColor, padding: '48px', position: 'relative', overflow: 'hidden' }}>
      <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', pointerEvents: 'none', zIndex: 0 }}>
        {showConnectors && branches.map((branch, idx) => {
          const pos = getNodePosition(idx, branches.length, branchDistance);
          return (
            <line key={idx} x1="50%" y1="50%" x2={`calc(50% + ${pos.x}px)`} y2={`calc(50% + ${pos.y}px)`} stroke={connectorColor} strokeWidth="2" />
          );
        })}
      </svg>

      <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', zIndex: 1 }}>
        <div style={{ width: centralNodeRadius + 'px', height: centralNodeRadius + 'px', borderRadius: '50%', backgroundColor: centralNodeColor, color: textColor, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: centralNodeSize + 'px', fontWeight: nodeWeight, textAlign: 'center', padding: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.12)' }}>
          {centralConcept}
        </div>
      </div>

      {branches.map((branch, idx) => {
        const pos = getNodePosition(idx, branches.length, branchDistance);
        const isExpanded = expandedBranches.has(branch.id);

        return (
          <div key={branch.id} style={{ position: 'absolute', top: '50%', left: '50%', transform: `translate(calc(-50% + ${pos.x}px), calc(-50% + ${pos.y}px))`, zIndex: 2 }}>
            <div
              className={`${p}-branch`}
              role="button"
              tabIndex={0}
              aria-expanded={isExpanded}
              onClick={() => toggleBranch(branch.id)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  toggleBranch(branch.id);
                }
              }}
              style={{ width: branchNodeRadius + 'px', height: branchNodeRadius + 'px', borderRadius: '50%', backgroundColor: branchNodeColor, color: textColor, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: branchNodeSize + 'px', fontWeight: nodeWeight, textAlign: 'center', padding: '12px', cursor: 'pointer', transition: reduced ? 'none' : 'all 0.3s ease-out', boxShadow: '0 2px 8px rgba(0,0,0,0.08)', transform: isExpanded ? 'scale(1.05)' : 'scale(1)' }}>
              {branch.text}
            </div>

            {isExpanded && branch.children.map((child, childIdx) => {
              const childPos = getNodePosition(childIdx, branch.children.length, 90);
              return (
                <div key={childIdx} style={{ position: 'absolute', top: '50%', left: '50%', transform: `translate(calc(-50% + ${childPos.x}px), calc(-50% + ${childPos.y}px))` }}>
                  <div className={`${p}-leaf`} style={{ width: '50px', height: '50px', borderRadius: '50%', backgroundColor: leafNodeColor, color: textColor, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '11px', fontWeight: nodeWeight, textAlign: 'center', padding: '8px', boxShadow: '0 1px 4px rgba(0,0,0,0.06)', animation: reduced ? 'none' : `${p}-leafIn 0.4s cubic-bezier(0.22, 1, 0.36, 1)` }}>
                    {child}
                  </div>
                </div>
              );
            })}
          </div>
        );
      })}

      <style>{`
        @keyframes ${p}-leafIn {
          from { opacity: 0; transform: scale(0.5); }
          to { opacity: 1; transform: scale(1); }
        }
        .${p}-branch:focus-visible {
          outline: 2px solid ${branchNodeColor};
          outline-offset: 3px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
    </div>
  );
}

