  "description": "Network graph with interconnected nodes showing relationships and dependencies, with hover highlighting",
  "editorElement": {
    "selector": ".network-graph-container",
    "displayName": "Network Graph",
    "archetype": "container",
    "data": {
      "showLabels": { "dataType": "booleanValue", "displayName": "Show Node Labels", "defaultValue": true, "group": "Content" },
      "showConnections": { "dataType": "booleanValue", "displayName": "Show Connections", "defaultValue": true, "group": "Content" },
      "nodes": { "dataType": "text", "displayName": "Nodes (Label@x,y;; between nodes)", "defaultValue": "Frontend@200,150;;API@400,150;;Database@600,150;;Auth@300,280;;Cache@500,280", "group": "Content" },
      "connections": { "dataType": "text", "displayName": "Connections (from-to, 1-based node order)", "defaultValue": "1-2,2-3,2-4,2-5,4-5", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "nodeColor": { "dataType": "color", "displayName": "Node Color", "defaultValue": "#495057", "group": "Colors" },
      "connectionColor": { "dataType": "color", "displayName": "Connection Color", "defaultValue": "#E9ECEF", "group": "Colors" },
      "labelColor": { "dataType": "color", "displayName": "Label Color", "defaultValue": "#212529", "group": "Colors" },
      "labelSize": { "dataType": "number", "displayName": "Label Size (px)", "defaultValue": 12, "group": "Typography" },
      "nodeSize": { "dataType": "select", "displayName": "Node Size", "defaultValue": "12px", "options": ["8px", "12px", "16px", "20px"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'ng' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const showLabels = bool(config?.showLabels, true);
  const showConnections = bool(config?.showConnections, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const nodeColor = config?.nodeColor || "#495057";
  const connectionColor = config?.connectionColor || "#E9ECEF";
  const labelColor = config?.labelColor || "#212529";
  const labelSize = parseInt(config?.labelSize || '12');
  const nodeSize = parseInt(config?.nodeSize || '12');

  const defaultNodes = [
    { id: 1, x: 200, y: 150, label: "Frontend" },
    { id: 2, x: 400, y: 150, label: "API" },
    { id: 3, x: 600, y: 150, label: "Database" },
    { id: 4, x: 300, y: 280, label: "Auth" },
    { id: 5, x: 500, y: 280, label: "Cache" }
  ];
  const defaultConnections = [[1, 2], [2, 3], [2, 4], [2, 5], [4, 5]];

  const parsedNodes = String(config?.nodes || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [label, coords] = entry.split('@');
      const [x, y] = String(coords || '').split(',').map((n) => parseFloat(n));
      return { id: i + 1, x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y, label: (label || `Node ${i + 1}`).trim() };
    });

  const parsedConnections = String(config?.connections || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((pair) => pair.split('-').map((n) => parseInt(n)))
    .filter(([from, to]) => !isNaN(from) && !isNaN(to));

  const nodes = parsedNodes.length > 0 ? parsedNodes : defaultNodes;
  const connections = parsedConnections.length > 0 ? parsedConnections : defaultConnections;

  return (
    <div className={`network-graph-container ${p}`} style={{ width: '100%', minHeight: '400px', backgroundColor, padding: '32px', position: 'relative' }}>
      <style>{`
        .${p}-node {
          transition: ${reduced ? 'none' : 'transform 0.2s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.2s ease-out'};
          transform-box: fill-box;
          transform-origin: center;
        }
        .${p}-node:hover {
          opacity: 0.85;
          transform: ${reduced ? 'none' : 'scale(1.2)'};
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <svg style={{ width: '100%', height: '400px' }}>
        {showConnections && connections.map(([from, to], idx) => {
          const fromNode = nodes.find((n) => n.id === from);
          const toNode = nodes.find((n) => n.id === to);
          return fromNode && toNode ? (
            <line key={idx} x1={fromNode.x} y1={fromNode.y} x2={toNode.x} y2={toNode.y} stroke={connectionColor} strokeWidth="2" />
          ) : null;
        })}
        {nodes.map((node) => (
          <g key={node.id}>
            <circle className={`${p}-node`} cx={node.x} cy={node.y} r={nodeSize} fill={nodeColor} stroke="#FFFFFF" strokeWidth="2" />
            {showLabels && (
              <text x={node.x} y={node.y - nodeSize - 8} fill={labelColor} fontSize={labelSize + 'px'} fontWeight="400" textAnchor="middle">
                {node.label}
              </text>
            )}
          </g>
        ))}
      </svg>
    </div>
  );
}

diagrams-ganttchart:
const MANIFEST = {
  "type": "Diagrams.GanttChart",
  "description": "Gantt chart for project timeline visualization with task dependencies",
  "editorElement": {
    "selector": ".gantt-chart-container",
    "displayName": "Gantt Chart",
    "archetype": "container",
    "data": {
      "title": { "dataType": "text", "displayName": "Chart Title", "defaultValue": "Project Timeline", "group": "Content" },
      "showDependencies": { "dataType": "booleanValue", "displayName": "Show Dependencies", "defaultValue": true, "group": "Content" },
      "tasks": { "dataType": "text", "displayName": "Tasks (Name@start,duration,progress|dependsOnTask#,...;; between tasks)", "defaultValue": "Research@0,2,100;;Design@2,3,100|1;;Development@4,5,60|2;;Testing@8,2,0|3", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "titleColor": { "dataType": "color", "displayName": "Title Color", "defaultValue": "#212529", "group": "Colors" },
      "taskBarColor": { "dataType": "color", "displayName": "Task Bar Color", "defaultValue": "#495057", "group": "Colors" },
      "completedColor": { "dataType": "color", "displayName": "Completed Color", "defaultValue": "#343A40", "group": "Colors" },
      "gridColor": { "dataType": "color", "displayName": "Grid Color", "defaultValue": "#F1F3F5", "group": "Colors" },
      "dependencyColor": { "dataType": "color", "displayName": "Dependency Line Color", "defaultValue": "#ADB5BD", "group": "Colors" },
      "titleSize": { "dataType": "number", "displayName": "Title Size (px)", "defaultValue": 24, "group": "Typography" },
      "taskTextSize": { "dataType": "number", "displayName": "Task Text Size (px)", "defaultValue": 13, "group": "Typography" },
      "barHeight": { "dataType": "select", "displayName": "Bar Height", "defaultValue": "32px", "options": ["24px", "32px", "40px"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'gc' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const title = config?.title || "Project Timeline";
  const showDependencies = bool(config?.showDependencies, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const titleColor = config?.titleColor || "#212529";
  const taskBarColor = config?.taskBarColor || "#495057";
  const completedColor = config?.completedColor || "#343A40";
  const gridColor = config?.gridColor || "#F1F3F5";
  const dependencyColor = config?.dependencyColor || "#ADB5BD";
  const titleSize = parseInt(config?.titleSize || '24');
  const taskTextSize = parseInt(config?.taskTextSize || '13');
  const barHeight = parseInt(config?.barHeight || '32');

  const defaultTasks = [
    { id: 1, name: "Research", start: 0, duration: 2, progress: 100, deps: [] },
    { id: 2, name: "Design", start: 2, duration: 3, progress: 100, deps: [1] },
    { id: 3, name: "Development", start: 4, duration: 5, progress: 60, deps: [2] },
    { id: 4, name: "Testing", start: 8, duration: 2, progress: 0, deps: [3] }
  ];

  const parsedTasks = String(config?.tasks || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [name, rest] = entry.split('@');
      const [numsStr, depsStr] = String(rest || '').split('|');
      const [start, duration, progress] = numsStr.split(',').map((n) => parseFloat(n));
      const deps = depsStr ? depsStr.split(',').map((n) => parseInt(n)).filter((n) => !isNaN(n)) : [];
      return {
        id: i + 1,
        name: (name || `Task ${i + 1}`).trim(),
        start: isNaN(start) ? 0 : start,
        duration: isNaN(duration) ? 1 : duration,
        progress: isNaN(progress) ? 0 : progress,
        deps
      };
    });

  const tasks = parsedTasks.length > 0 ? parsedTasks : defaultTasks;
  const weeks = Math.max(1, ...tasks.map((t) => t.start + t.duration));
  const rowHeight = barHeight + 8;

  // SVG <path> "d" coordinates must be plain numbers (no "%"), so the dependency
  // lines need the chart column's real pixel width, not a CSS percentage.
  const chartRef = React.useRef(null);
  const [chartWidth, setChartWidth] = React.useState(600);
  React.useEffect(() => {
    const el = chartRef.current;
    if (!el) return undefined;
    const measure = () => setChartWidth(el.clientWidth || 600);
    measure();
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(measure) : null;
    if (ro) ro.observe(el);
    window.addEventListener('resize', measure);
    return () => { if (ro) ro.disconnect(); window.removeEventListener('resize', measure); };
  }, []);

  return (
    <div className={`gantt-chart-container ${p}`} style={{ width: '100%', minHeight: '400px', backgroundColor, padding: '32px' }}>
      <style>{`
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <h2 style={{ fontSize: titleSize + 'px', fontWeight: '500', color: titleColor, margin: '0 0 24px 0' }}>{title}</h2>
      <div style={{ display: 'flex', gap: '16px' }}>
        <div style={{ width: '150px' }}>
          {tasks.map((task) => (
            <div key={task.id} style={{ height: barHeight + 'px', display: 'flex', alignItems: 'center', fontSize: taskTextSize + 'px', color: titleColor, fontWeight: '400', marginBottom: '8px' }}>
              {task.name}
            </div>
          ))}
        </div>
        <div ref={chartRef} style={{ flex: 1, position: 'relative' }}>
          <div style={{ display: 'flex', height: '100%', borderLeft: `1px solid ${gridColor}` }}>
            {Array.from({ length: weeks }).map((_, i) => (
              <div key={i} style={{ flex: 1, borderRight: `1px solid ${gridColor}`, height: '100%' }} />
            ))}
          </div>

          {showDependencies && (
            <svg
              width={chartWidth}
              height={tasks.length * rowHeight}
              style={{ position: 'absolute', top: 0, left: 0, pointerEvents: 'none', overflow: 'visible' }}
            >
              <defs>
                <marker id={`${p}-arrow`} markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto">
                  <path d="M0,0 L8,4 L0,8 Z" fill={dependencyColor} />
                </marker>
              </defs>
              {tasks.map((task, idx) =>
                task.deps.map((depId) => {
                  const depIdx = tasks.findIndex((t) => t.id === depId);
                  if (depIdx === -1) return null;
                  const depTask = tasks[depIdx];
                  const x1 = ((depTask.start + depTask.duration) / weeks) * chartWidth;
                  const y1 = depIdx * rowHeight + barHeight / 2;
                  const x2 = (task.start / weeks) * chartWidth;
                  const y2 = idx * rowHeight + barHeight / 2;
                  return (
                    <path
                      key={`${depId}-${task.id}`}
                      d={`M ${x1} ${y1} L ${x2} ${y2}`}
                      stroke={dependencyColor}
                      strokeWidth="1.5"
                      strokeDasharray="4 3"
                      fill="none"
                      markerEnd={`url(#${p}-arrow)`}
                    />
                  );
                })
              )}
            </svg>
          )}

          {tasks.map((task, idx) => (
            <div key={task.id} style={{ position: 'absolute', top: (idx * rowHeight) + 'px', left: ((task.start / weeks) * 100) + '%', width: ((task.duration / weeks) * 100) + '%', height: barHeight + 'px' }}>
              <div style={{ backgroundColor: taskBarColor, height: '100%', borderRadius: '4px', position: 'relative', overflow: 'hidden' }}>
                <div style={{ backgroundColor: completedColor, width: task.progress + '%', height: '100%', transition: reduced ? 'none' : 'width 0.5s ease-out' }} />
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

