      "nodeColor": { "dataType": "color", "displayName": "Node Color", "defaultValue": "#212529", "group": "Colors" },
      "labelColor": { "dataType": "color", "displayName": "Label Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "titleSize": { "dataType": "number", "displayName": "Title Size (px)", "defaultValue": 24, "group": "Typography" },
      "labelSize": { "dataType": "number", "displayName": "Label Size (px)", "defaultValue": 13, "group": "Typography" },
      "flowOpacity": { "dataType": "select", "displayName": "Flow Opacity", "defaultValue": "0.5", "options": ["0.3", "0.4", "0.5", "0.6"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'sk' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const title = config?.title || "Traffic Flow";
  const showValues = config?.showValues !== false;
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const titleColor = config?.titleColor || "#212529";
  const flowColor = config?.flowColor || "#495057";
  const nodeColor = config?.nodeColor || "#212529";
  const labelColor = config?.labelColor || "#FFFFFF";
  const titleSize = parseInt(config?.titleSize || '24');
  const labelSize = parseInt(config?.labelSize || '13');
  const flowOpacity = parseFloat(config?.flowOpacity || '0.5');

  const defaultNodes = [
    { x: 50, y: 100, label: "Source", height: 120 },
    { x: 300, y: 80, label: "Channel A", height: 60 },
    { x: 300, y: 180, label: "Channel B", height: 80 },
    { x: 550, y: 100, label: "Destination", height: 120 }
  ];
  const defaultFlows = [
    { from: 0, to: 1, value: 60 },
    { from: 0, to: 2, value: 80 },
    { from: 1, to: 3, value: 60 },
    { from: 2, to: 3, value: 80 }
  ];

  const parsedNodes = String(config?.nodes || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [label, nums] = entry.split('@');
      const [x, y, height] = String(nums || '').split(',').map((n) => parseFloat(n));
      return { label: (label || `Node ${i + 1}`).trim(), x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y, height: isNaN(height) ? 60 : height };
    });

  const parsedFlows = String(config?.flows || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry) => {
      const [pair, valueStr] = entry.split(':');
      const [from, to] = pair.split('-').map((n) => parseInt(n));
      return { from, to, value: parseFloat(valueStr) || 0 };
    })
    .filter((f) => !isNaN(f.from) && !isNaN(f.to));

  const nodes = parsedNodes.length > 0 ? parsedNodes : defaultNodes;
  const flows = parsedFlows.length > 0 ? parsedFlows : defaultFlows;

  return (
    <div className={`sankey-diagram-container ${p}`} style={{ width: '100%', minHeight: '400px', backgroundColor, padding: '32px' }}>
      <style>{`
        .${p}-flow {
          transition: ${reduced ? 'none' : 'opacity 0.2s ease-out'};
        }
        .${p}-flow:hover {
          opacity: ${Math.min(1, flowOpacity + 0.3)};
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <h2 style={{ fontSize: titleSize + 'px', fontWeight: '500', color: titleColor, margin: '0 0 24px 0' }}>{title}</h2>
      <svg width="100%" height="300" viewBox="0 0 600 300">
        {flows.map((flow, idx) => {
          const fromNode = nodes[flow.from];
          const toNode = nodes[flow.to];
          if (!fromNode || !toNode) return null;
          const y1 = fromNode.y + fromNode.height / 2;
          const y2 = toNode.y + toNode.height / 2;
          const midX = (fromNode.x + toNode.x) / 2;
          return (
            <g key={idx}>
              <path
                className={`${p}-flow`}
                d={`M ${fromNode.x + 40} ${y1} C ${midX} ${y1}, ${midX} ${y2}, ${toNode.x} ${y2}`}
                stroke={flowColor}
                strokeWidth={flow.value / 2}
                fill="none"
                opacity={flowOpacity}
              />
              {showValues && (
                <text x={midX} y={(y1 + y2) / 2 - 6} fill={titleColor} fontSize={Math.max(10, labelSize - 2) + 'px'} fontWeight="500" textAnchor="middle">
                  {flow.value}
                </text>
              )}
            </g>
          );
        })}
        {nodes.map((node, idx) => (
          <g key={idx}>
            <rect x={node.x} y={node.y} width="40" height={node.height} fill={nodeColor} rx="4" />
            <text x={node.x + 20} y={node.y + node.height / 2} fill={labelColor} fontSize={labelSize + 'px'} fontWeight="400" textAnchor="middle" dominantBaseline="middle">
              {node.label}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}

