diagrams-hierarchytree:
const MANIFEST = {
  "type": "Diagrams.HierarchyTree",
  "description": "Vertical hierarchy tree with parent-child relationships and expand/collapse",
  "editorElement": {
    "selector": ".hierarchy-tree-container",
    "displayName": "Hierarchy Tree",
    "archetype": "container",
    "data": {
      "rootLabel": { "dataType": "text", "displayName": "Root Label", "defaultValue": "Root Node", "group": "Content" },
      "nodes": { "dataType": "text", "displayName": "Nodes (Label|ParentLabel, ROOT = root node;; between nodes)", "defaultValue": "Child 1|ROOT;;Grandchild 1-1|Child 1;;Grandchild 1-2|Child 1;;Child 2|ROOT;;Grandchild 2-1|Child 2", "group": "Content" },
      "showIcons": { "dataType": "booleanValue", "displayName": "Show Node Icons", "defaultValue": true, "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "nodeBackgroundColor": { "dataType": "color", "displayName": "Node Background", "defaultValue": "#F8F9FA", "group": "Colors" },
      "nodeBorderColor": { "dataType": "color", "displayName": "Node Border", "defaultValue": "#E9ECEF", "group": "Colors" },
      "nodeTextColor": { "dataType": "color", "displayName": "Node Text Color", "defaultValue": "#212529", "group": "Colors" },
      "connectorColor": { "dataType": "color", "displayName": "Connector Color", "defaultValue": "#CED4DA", "group": "Colors" },
      "nodeTextSize": { "dataType": "number", "displayName": "Node Text Size (px)", "defaultValue": 14, "group": "Typography" },
      "nodeTextWeight": { "dataType": "select", "displayName": "Node Text Weight", "defaultValue": "400", "options": ["300", "400", "500"], "group": "Typography" },
      "nodeCornerRadius": { "dataType": "select", "displayName": "Node Corner Radius", "defaultValue": "6px", "options": ["0px", "4px", "6px", "8px"], "group": "Layout" },
      "verticalSpacing": { "dataType": "select", "displayName": "Vertical Spacing", "defaultValue": "60px", "options": ["40px", "60px", "80px"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'ht' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);
  const [expanded, setExpanded] = React.useState(new Set(['root']));

  const rootLabel = config?.rootLabel || "Root Node";
  const showIcons = bool(config?.showIcons, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const nodeBackgroundColor = config?.nodeBackgroundColor || "#F8F9FA";
  const nodeBorderColor = config?.nodeBorderColor || "#E9ECEF";
  const nodeTextColor = config?.nodeTextColor || "#212529";
  const connectorColor = config?.connectorColor || "#CED4DA";
  const nodeTextSize = parseInt(config?.nodeTextSize || '14');
  const nodeTextWeight = config?.nodeTextWeight || "400";
  const nodeCornerRadius = config?.nodeCornerRadius || "6px";
  const verticalSpacing = config?.verticalSpacing || "60px";

  const defaultTree = {
    id: 'root', label: rootLabel, children: [
      { id: 'c1', label: "Child 1", children: [{ id: 'c1-1', label: "Grandchild 1-1" }, { id: 'c1-2', label: "Grandchild 1-2" }] },
      { id: 'c2', label: "Child 2", children: [{ id: 'c2-1', label: "Grandchild 2-1" }] }
    ]
  };

  const parsedEntries = String(config?.nodes || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry) => {
      const [label, parent] = entry.split('|');
      return { label: (label || '').trim(), parent: (parent || 'ROOT').trim() };
    })
    .filter((e) => e.label);

  let tree = defaultTree;
  if (parsedEntries.length > 0) {
    const root = { id: 'root', label: rootLabel, children: [] };
    const byLabel = new Map();
    byLabel.set('ROOT', root);
    parsedEntries.forEach((e, idx) => {
      byLabel.set(e.label, { id: `n${idx}`, label: e.label, children: [] });
    });
    parsedEntries.forEach((e) => {
      const node = byLabel.get(e.label);
      const parentNode = byLabel.get(e.parent) || root;
      parentNode.children.push(node);
    });
    tree = root;
  }

  const toggle = (id) => {
    setExpanded((prev) => {
      const n = new Set(prev);
      n.has(id) ? n.delete(id) : n.add(id);
      return n;
    });
  };

  const renderNode = (node, depth = 0) => {
    const isExp = expanded.has(node.id);
    const hasChildren = node.children && node.children.length > 0;
    return (
      <div key={node.id} style={{ marginLeft: depth > 0 ? '40px' : '0', marginTop: depth > 0 ? verticalSpacing : '0' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          {depth > 0 && <div style={{ width: '24px', height: '24px', borderLeft: `2px solid ${connectorColor}`, borderBottom: `2px solid ${connectorColor}`, marginTop: '-12px' }} />}
          <div
            className={`${p}-node`}
            role={hasChildren ? 'button' : undefined}
            tabIndex={hasChildren ? 0 : undefined}
            aria-expanded={hasChildren ? isExp : undefined}
            onClick={() => hasChildren && toggle(node.id)}
            onKeyDown={(e) => {
              if (hasChildren && (e.key === 'Enter' || e.key === ' ')) {
                e.preventDefault();
                toggle(node.id);
              }
            }}
            style={{ backgroundColor: nodeBackgroundColor, border: `1px solid ${nodeBorderColor}`, borderRadius: nodeCornerRadius, padding: '12px 16px', cursor: hasChildren ? 'pointer' : 'default', transition: reduced ? 'none' : 'all 0.25s ease-out', boxShadow: '0 1px 3px rgba(0,0,0,0.06)', display: 'flex', alignItems: 'center', gap: '8px' }}
          >
            {showIcons && <span style={{ fontSize: '16px' }}>📁</span>}
            <span style={{ fontSize: nodeTextSize + 'px', fontWeight: nodeTextWeight, color: nodeTextColor }}>{node.label}</span>
            {hasChildren && <span style={{ fontSize: '10px', opacity: 0.7, transform: isExp ? 'rotate(90deg)' : 'rotate(0)', transition: reduced ? 'none' : 'transform 0.25s ease-out' }}>▶</span>}
          </div>
        </div>
        {hasChildren && isExp && (
          <div style={{ marginTop: '8px', opacity: 1, animation: reduced ? 'none' : `${p}-fadeIn 0.4s ease-out` }}>
            {node.children.map((child) => renderNode(child, depth + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className={`hierarchy-tree-container ${p}`} style={{ width: '100%', minHeight: '400px', backgroundColor, padding: '32px' }}>
      <style>{`
        @keyframes ${p}-fadeIn {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .${p}-node:focus-visible {
          outline: 2px solid ${connectorColor};
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      {renderNode(tree)}
    </div>
  );
}

