    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'cl' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const connectorStyle = config?.connectorStyle || "curved";
  const showArrows = config?.showArrows !== false;
  const showLabels = config?.showLabels !== false;
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const connectorColor = config?.connectorColor || "#495057";
  const nodeColor = config?.nodeColor || "#F8F9FA";
  const nodeBorderColor = config?.nodeBorderColor || "#E9ECEF";
  const labelColor = config?.labelColor || "#6C757D";
  const labelSize = parseInt(config?.labelSize || '11');
  const connectorWidth = config?.connectorWidth || "2px";

  const getPath = (x1, y1, x2, y2, style) => {
    switch (style) {
      case 'straight':
        return `M ${x1} ${y1} L ${x2} ${y2}`;
      case 'curved': {
        const mx = (x1 + x2) / 2;
        return `M ${x1} ${y1} Q ${mx} ${y1} ${mx} ${(y1 + y2) / 2} T ${x2} ${y2}`;
      }
      case 'stepped': {
        const my = (y1 + y2) / 2;
        return `M ${x1} ${y1} L ${x1} ${my} L ${x2} ${my} L ${x2} ${y2}`;
      }
      case 'orthogonal':
        return `M ${x1} ${y1} L ${x2} ${y1} L ${x2} ${y2}`;
      default:
        return `M ${x1} ${y1} L ${x2} ${y2}`;
    }
  };

  const arrowId = `${p}-arrow`;

  return (
    <div className={`connector-lines-container ${p}`} style={{ width: '100%', minHeight: '400px', backgroundColor, padding: '32px' }}>
      <style>{`
        .${p}-path {
          transition: ${reduced ? 'none' : 'stroke-width 0.2s ease-out, opacity 0.2s ease-out'};
        }
        .${p}-path:hover {
          opacity: 0.7;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <svg width="100%" height="400">
        <defs>
          <marker id={arrowId} markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto">
            <polygon points="0 0, 10 3, 0 6" fill={connectorColor} />
          </marker>
        </defs>
        <path className={`${p}-path`} d={getPath(100, 100, 300, 100, connectorStyle)} stroke={connectorColor} strokeWidth={connectorWidth} fill="none" markerEnd={showArrows ? `url(#${arrowId})` : ""} />
        <path className={`${p}-path`} d={getPath(100, 200, 300, 300, connectorStyle)} stroke={connectorColor} strokeWidth={connectorWidth} fill="none" markerEnd={showArrows ? `url(#${arrowId})` : ""} />
        <circle cx="100" cy="100" r="20" fill={nodeColor} stroke={nodeBorderColor} strokeWidth="2" />
        <circle cx="300" cy="100" r="20" fill={nodeColor} stroke={nodeBorderColor} strokeWidth="2" />
        <circle cx="100" cy="200" r="20" fill={nodeColor} stroke={nodeBorderColor} strokeWidth="2" />
        <circle cx="300" cy="300" r="20" fill={nodeColor} stroke={nodeBorderColor} strokeWidth="2" />
        {showLabels && (
