const MANIFEST = {
  "type": "Diagrams.StateMachine",
  "description": "State machine diagram with states, transitions, and interactive highlights",
  "editorElement": {
    "selector": ".state-machine-container",
    "displayName": "State Machine",
    "archetype": "container",
    "data": {
      "title": { "dataType": "text", "displayName": "Machine Title", "defaultValue": "User Authentication Flow", "group": "Content" },
      "showTransitionLabels": { "dataType": "booleanValue", "displayName": "Show Transition Labels", "defaultValue": true, "group": "Content" },
      "states": { "dataType": "text", "displayName": "States (Label@x,y;; between states)", "defaultValue": "Idle@100,150;;Authenticating@300,150;;Authenticated@500,150;;Error@300,280", "group": "Content" },
      "transitions": { "dataType": "text", "displayName": "Transitions (fromState-toState:label, 0-based state order)", "defaultValue": "0-1:login,1-2:success,1-3:failure,3-0:reset", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "titleColor": { "dataType": "color", "displayName": "Title Color", "defaultValue": "#212529", "group": "Colors" },
      "stateColor": { "dataType": "color", "displayName": "State Color", "defaultValue": "#F8F9FA", "group": "Colors" },
      "stateBorderColor": { "dataType": "color", "displayName": "State Border", "defaultValue": "#E9ECEF", "group": "Colors" },
      "activeStateColor": { "dataType": "color", "displayName": "Active State Color", "defaultValue": "#495057", "group": "Colors" },
      "transitionColor": { "dataType": "color", "displayName": "Transition Color", "defaultValue": "#6C757D", "group": "Colors" },
      "titleSize": { "dataType": "number", "displayName": "Title Size (px)", "defaultValue": 24, "group": "Typography" },
      "stateTextSize": { "dataType": "number", "displayName": "State Text Size (px)", "defaultValue": 13, "group": "Typography" },
      "stateTextWeight": { "dataType": "select", "displayName": "State Text Weight", "defaultValue": "400", "options": ["300", "400", "500"], "group": "Typography" },
      "stateCornerRadius": { "dataType": "select", "displayName": "State Corner Radius", "defaultValue": "6px", "options": ["0px", "4px", "6px", "8px", "12px"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'sm' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);
  const [activeState, setActiveState] = React.useState(0);

  const title = config?.title || "User Authentication Flow";
  const showTransitionLabels = bool(config?.showTransitionLabels, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const titleColor = config?.titleColor || "#212529";
  const stateColor = config?.stateColor || "#F8F9FA";
  const stateBorderColor = config?.stateBorderColor || "#E9ECEF";
  const activeStateColor = config?.activeStateColor || "#495057";
  const transitionColor = config?.transitionColor || "#6C757D";
  const titleSize = parseInt(config?.titleSize || '24');
  const stateTextSize = parseInt(config?.stateTextSize || '13');
  const stateTextWeight = config?.stateTextWeight || "400";
  const stateCornerRadius = parseInt(config?.stateCornerRadius || '6');

  const defaultStates = [
    { id: 0, label: "Idle", x: 100, y: 150 },
    { id: 1, label: "Authenticating", x: 300, y: 150 },
    { id: 2, label: "Authenticated", x: 500, y: 150 },
    { id: 3, label: "Error", x: 300, y: 280 }
  ];
  const defaultTransitions = [[0, 1, "login"], [1, 2, "success"], [1, 3, "failure"], [3, 0, "reset"]];

  const parsedStates = String(config?.states || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [label, coords] = entry.split('@');
      const [x, y] = String(coords || '').split(',').map((n) => parseFloat(n));
      return { id: i, label: (label || `State ${i + 1}`).trim(), x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y };
    });

  const parsedTransitions = String(config?.transitions || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry) => {
      const [pair, label] = entry.split(':');
      const [from, to] = pair.split('-').map((n) => parseInt(n));
      return [from, to, (label || '').trim()];
    })
    .filter(([from, to]) => !isNaN(from) && !isNaN(to));

  const states = parsedStates.length > 0 ? parsedStates : defaultStates;
  const transitions = parsedTransitions.length > 0 ? parsedTransitions : defaultTransitions;
  const arrowId = `${p}-arrow-trans`;

  return (
    <div className={`state-machine-container ${p}`} style={{ width: '100%', minHeight: '450px', backgroundColor, padding: '32px' }}>
      <style>{`
        .${p}-state {
          transition: ${reduced ? 'none' : 'opacity 0.2s ease-out'};
        }
        .${p}-state:hover rect {
          opacity: 0.85;
        }
        .${p}-state:focus-visible rect {
          outline: 2px solid ${activeStateColor};
          outline-offset: 2px;
        }
        .${p}-state rect {
          transition: ${reduced ? 'none' : 'fill 0.25s ease-out'};
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <h2 style={{ fontSize: titleSize + 'px', fontWeight: '500', color: titleColor, margin: '0 0 32px 0' }}>{title}</h2>
      <svg width="100%" height="350">
        <defs>
          <marker id={arrowId} markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto">
            <polygon points="0 0, 10 3, 0 6" fill={transitionColor} />
          </marker>
        </defs>
        {transitions.map(([from, to, label], idx) => {
          const s1 = states[from];
          const s2 = states[to];
          if (!s1 || !s2) return null;
          return (
            <g key={idx}>
              <path d={`M ${s1.x + 60} ${s1.y + 25} L ${s2.x} ${s2.y + 25}`} stroke={transitionColor} strokeWidth="2" fill="none" markerEnd={`url(#${arrowId})`} />
              {showTransitionLabels && (
                <text x={(s1.x + s2.x) / 2 + 30} y={(s1.y + s2.y) / 2 + 15} fill={transitionColor} fontSize="11px" fontWeight="400">
                  {label}
                </text>
              )}
            </g>
          );
        })}
        {states.map((state) => (
          <g
            key={state.id}
            className={`${p}-state`}
            role="button"
            tabIndex={0}
            aria-pressed={activeState === state.id}
            onClick={() => setActiveState(state.id)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                setActiveState(state.id);
              }
            }}
            style={{ cursor: 'pointer' }}
          >
            <rect x={state.x} y={state.y} width="120" height="50" rx={stateCornerRadius} fill={activeState === state.id ? activeStateColor : stateColor} stroke={stateBorderColor} strokeWidth="2" />
            <text x={state.x + 60} y={state.y + 30} fill={activeState === state.id ? "#FFFFFF" : titleColor} fontSize={stateTextSize + 'px'} fontWeight={stateTextWeight} textAnchor="middle" dominantBaseline="middle" style={{ pointerEvents: 'none' }}>
              {state.label}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
}

