    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const systemName = config?.systemName || "E-Commerce System";
  const showSystemBoundary = bool(config?.showSystemBoundary, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const systemBorderColor = config?.systemBorderColor || "#E9ECEF";
  const actorColor = config?.actorColor || "#495057";
  const useCaseColor = config?.useCaseColor || "#F8F9FA";
  const useCaseBorderColor = config?.useCaseBorderColor || "#E9ECEF";
  const relationshipColor = config?.relationshipColor || "#CED4DA";
  const textColor = config?.textColor || "#212529";
  const systemNameSize = parseInt(config?.systemNameSize || '16');
  const useCaseTextSize = parseInt(config?.useCaseTextSize || '12');
  const actorTextSize = parseInt(config?.actorTextSize || '13');

  const UC_RX = 70;
  const UC_RY = 35;

  const defaultActors = [{ name: "Customer", x: 100, y: 150 }, { name: "Admin", x: 650, y: 200 }];
  const defaultUseCases = [
    { name: "Browse Products", x: 300, y: 120 },
    { name: "Place Order", x: 450, y: 120 },
    { name: "Make Payment", x: 300, y: 220 },
    { name: "Manage Inventory", x: 450, y: 220 }
  ];
  const defaultRelationships = [[0, 0], [0, 1], [0, 2], [1, 3]];

  const parsePoints = (raw, labelPrefix) =>
    String(raw || '')
      .split(';;')
      .map((s) => s.trim())
      .filter(Boolean)
      .map((entry, i) => {
        const [name, coords] = entry.split('@');
        const [x, y] = String(coords || '').split(',').map((n) => parseFloat(n));
        return { name: (name || `${labelPrefix} ${i + 1}`).trim(), x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y };
      });

  const parsedActors = parsePoints(config?.actors, 'Actor');
  const parsedUseCases = parsePoints(config?.useCases, 'Use Case');
  const parsedRelationships = String(config?.relationships || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((pair) => pair.split('-').map((n) => parseInt(n)))
    .filter(([a, u]) => !isNaN(a) && !isNaN(u));

  const actors = parsedActors.length > 0 ? parsedActors : defaultActors;
  const useCases = parsedUseCases.length > 0 ? parsedUseCases : defaultUseCases;
  const relationships = parsedRelationships.length > 0 ? parsedRelationships : defaultRelationships;

  const renderActor = (actor, idx) => (
    <g key={idx}>
      <ellipse cx={actor.x} cy={actor.y} rx="15" ry="25" fill="none" stroke={actorColor} strokeWidth="2" />
      <line x1={actor.x} y1={actor.y + 25} x2={actor.x} y2={actor.y + 70} stroke={actorColor} strokeWidth="2" />
      <line x1={actor.x} y1={actor.y + 40} x2={actor.x - 20} y2={actor.y + 60} stroke={actorColor} strokeWidth="2" />
      <line x1={actor.x} y1={actor.y + 40} x2={actor.x + 20} y2={actor.y + 60} stroke={actorColor} strokeWidth="2" />
      <line x1={actor.x} y1={actor.y + 70} x2={actor.x - 20} y2={actor.y + 100} stroke={actorColor} strokeWidth="2" />
      <line x1={actor.x} y1={actor.y + 70} x2={actor.x + 20} y2={actor.y + 100} stroke={actorColor} strokeWidth="2" />
      <text x={actor.x} y={actor.y + 125} fill={textColor} fontSize={actorTextSize + 'px'} fontWeight="400" textAnchor="middle">{actor.name}</text>
    </g>
  );

  return (
    <div className={`usecase-diagram-container ${p}`} style={{ width: '100%', minHeight: '500px', backgroundColor, padding: '32px' }}>
      <style>{`
        .${p}-uc ellipse {
          transition: ${reduced ? 'none' : 'opacity 0.2s ease-out'};
        }
        .${p}-uc:hover ellipse {
          opacity: 0.7;
        }
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <svg width="100%" height="450" viewBox="0 0 750 450">
        {showSystemBoundary && (
          <>
            <rect x="150" y="50" width="450" height="350" rx="8" fill="none" stroke={systemBorderColor} strokeWidth="2" strokeDasharray="8" />
            <text x="375" y="35" fill={textColor} fontSize={systemNameSize + 'px'} fontWeight="500" textAnchor="middle">{systemName}</text>
          </>
        )}

        {relationships.map(([actorIdx, ucIdx], idx) => {
          const actor = actors[actorIdx];
          const uc = useCases[ucIdx];
          if (!actor || !uc) return null;
          const dir = actor.x < uc.x ? 1 : -1;
          const x1 = actor.x + dir * 15;
          const y1 = actor.y + 45;
          const x2 = uc.x - dir * UC_RX;
          const y2 = uc.y + 5;
          return <line key={idx} x1={x1} y1={y1} x2={x2} y2={y2} stroke={relationshipColor} strokeWidth="2" />;
        })}

        {actors.map(renderActor)}

        {useCases.map((uc, idx) => (
          <g key={idx} className={`${p}-uc`}>
            <ellipse cx={uc.x} cy={uc.y} rx={UC_RX} ry={UC_RY} fill={useCaseColor} stroke={useCaseBorderColor} strokeWidth="2" />
            <text x={uc.x} y={uc.y + 5} fill={textColor} fontSize={useCaseTextSize + 'px'} fontWeight="400" textAnchor="middle">{uc.name}</text>
          </g>
        ))}
      </svg>
    </div>
  );
}

diagrams-erdiagram:
const MANIFEST = {
  "type": "Diagrams.ERDiagram",
  "description": "Entity-Relationship diagram showing database entities and their relationships",
  "editorElement": {
    "selector": ".er-diagram-container",
    "displayName": "ER Diagram",
    "archetype": "container",
    "data": {
      "title": { "dataType": "text", "displayName": "Diagram Title", "defaultValue": "Database Schema", "group": "Content" },
      "showAttributes": { "dataType": "booleanValue", "displayName": "Show Attributes", "defaultValue": true, "group": "Content" },
      "entities": { "dataType": "text", "displayName": "Entities (Name|attr,attr,attr@x,y;; between entities)", "defaultValue": "User|id,email,name@100,100;;Order|id,date,total@350,100;;Product|id,name,price@350,280", "group": "Content" },
      "relationships": { "dataType": "text", "displayName": "Relationships (fromEntity-toEntity@label, 0-based order)", "defaultValue": "0-1@1:N,1-2@N:M", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "titleColor": { "dataType": "color", "displayName": "Title Color", "defaultValue": "#212529", "group": "Colors" },
      "entityColor": { "dataType": "color", "displayName": "Entity Color", "defaultValue": "#F8F9FA", "group": "Colors" },
      "entityBorderColor": { "dataType": "color", "displayName": "Entity Border", "defaultValue": "#E9ECEF", "group": "Colors" },
      "relationshipColor": { "dataType": "color", "displayName": "Relationship Color", "defaultValue": "#495057", "group": "Colors" },
      "titleSize": { "dataType": "number", "displayName": "Title Size (px)", "defaultValue": 24, "group": "Typography" },
      "entityTextSize": { "dataType": "number", "displayName": "Entity Text Size (px)", "defaultValue": 14, "group": "Typography" },
      "attributeTextSize": { "dataType": "number", "displayName": "Attribute Text Size (px)", "defaultValue": 11, "group": "Typography" },
      "entityCornerRadius": { "dataType": "select", "displayName": "Entity Corner Radius", "defaultValue": "4px", "options": ["0px", "2px", "4px", "6px"], "group": "Layout" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'er' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const title = config?.title || "Database Schema";
  const showAttributes = bool(config?.showAttributes, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const titleColor = config?.titleColor || "#212529";
  const entityColor = config?.entityColor || "#F8F9FA";
  const entityBorderColor = config?.entityBorderColor || "#E9ECEF";
  const relationshipColor = config?.relationshipColor || "#495057";
  const titleSize = parseInt(config?.titleSize || '24');
  const entityTextSize = parseInt(config?.entityTextSize || '14');
  const attributeTextSize = parseInt(config?.attributeTextSize || '11');
  const entityCornerRadius = parseInt(config?.entityCornerRadius || '4');

  const defaultEntities = [
    { name: "User", x: 100, y: 100, attrs: ["id", "email", "name"] },
    { name: "Order", x: 350, y: 100, attrs: ["id", "date", "total"] },
    { name: "Product", x: 350, y: 280, attrs: ["id", "name", "price"] }
  ];
  const defaultRelationships = [[0, 1, "1:N"], [1, 2, "N:M"]];

  const parsedEntities = String(config?.entities || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [left, coords] = entry.split('@');
      const [name, attrsStr] = String(left || '').split('|');
      const attrs = String(attrsStr || '').split(',').map((a) => a.trim()).filter(Boolean);
      const [x, y] = String(coords || '').split(',').map((n) => parseFloat(n));
      return { name: (name || `Entity ${i + 1}`).trim(), attrs, x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y };
    });

  const parsedRelationships = String(config?.relationships || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry) => {
      const [pair, label] = entry.split('@');
      const [from, to] = pair.split('-').map((n) => parseInt(n));
      return [from, to, (label || '').trim()];
    })
    .filter(([from, to]) => !isNaN(from) && !isNaN(to));

  const entities = parsedEntities.length > 0 ? parsedEntities : defaultEntities;
  const relationships = parsedRelationships.length > 0 ? parsedRelationships : defaultRelationships;

  const entityHeight = (entity) => (showAttributes ? Math.max(60, 40 + entity.attrs.length * 18 + 20) : 60);

  return (
    <div className={`er-diagram-container ${p}`} style={{ width: '100%', minHeight: '500px', backgroundColor, padding: '32px' }}>
      <style>{`
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <h2 style={{ fontSize: titleSize + 'px', fontWeight: '500', color: titleColor, margin: '0 0 24px 0' }}>{title}</h2>
      <svg width="100%" height="420">
        {relationships.map(([fromIdx, toIdx, label], idx) => {
          const fromEntity = entities[fromIdx];
          const toEntity = entities[toIdx];
          if (!fromEntity || !toEntity) return null;
          const fromHeight = entityHeight(fromEntity);
          const toHeight = entityHeight(toEntity);
          const dx = toEntity.x - fromEntity.x;
          const dy = toEntity.y - fromEntity.y;
          let x1, y1, x2, y2, labelX, labelY;
          if (Math.abs(dx) >= Math.abs(dy)) {
            if (dx >= 0) { x1 = fromEntity.x + 150; x2 = toEntity.x; } else { x1 = fromEntity.x; x2 = toEntity.x + 150; }
            y1 = fromEntity.y + fromHeight / 2;
            y2 = toEntity.y + toHeight / 2;
            labelX = (x1 + x2) / 2 - 15;
            labelY = Math.min(y1, y2) - 10;
          } else {
            if (dy >= 0) { y1 = fromEntity.y + fromHeight; y2 = toEntity.y; } else { y1 = fromEntity.y; y2 = toEntity.y + toHeight; }
            x1 = fromEntity.x + 75;
            x2 = toEntity.x + 75;
            labelX = x1 + 10;
            labelY = (y1 + y2) / 2;
          }
          return (
            <g key={idx}>
              <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={relationshipColor} strokeWidth="2" />
              {label && <text x={labelX} y={labelY} fill={relationshipColor} fontSize="11px" fontWeight="400">{label}</text>}
            </g>
          );
        })}
        {entities.map((entity) => {
          const height = entityHeight(entity);
          return (
            <g key={entity.name}>
              <rect x={entity.x} y={entity.y} width="150" height={height} rx={entityCornerRadius} fill={entityColor} stroke={entityBorderColor} strokeWidth="2" />
              <rect x={entity.x} y={entity.y} width="150" height="30" rx={entityCornerRadius} fill={entityBorderColor} />
              <text x={entity.x + 75} y={entity.y + 20} fill={titleColor} fontSize={entityTextSize + 'px'} fontWeight="500" textAnchor="middle" dominantBaseline="middle">{entity.name}</text>
              {showAttributes && entity.attrs.map((attr, idx) => (
                <text key={idx} x={entity.x + 10} y={entity.y + 50 + idx * 18} fill={titleColor} fontSize={attributeTextSize + 'px'} fontWeight="400">• {attr}</text>
              ))}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

diagrams-dataflowdiagram:
const MANIFEST = {
  "type": "Diagrams.DataFlowDiagram",
  "description": "Data flow diagram showing processes, data stores, and external entities",
  "editorElement": {
    "selector": ".dataflow-diagram-container",
    "displayName": "Data Flow Diagram",
    "archetype": "container",
    "data": {
      "title": { "dataType": "text", "displayName": "System Title", "defaultValue": "Order Processing System", "group": "Content" },
      "showFlowLabels": { "dataType": "booleanValue", "displayName": "Show Flow Labels", "defaultValue": true, "group": "Content" },
      "nodes": { "dataType": "text", "displayName": "Nodes (entity|process|store:Label@x,y center;; between nodes)", "defaultValue": "entity:Customer@150,130;;process:Process Order@400,130;;store:Order Database@400,300", "group": "Content" },
      "flows": { "dataType": "text", "displayName": "Flows (fromNode-toNode@label, 0-based node order)", "defaultValue": "0-1@Order Data,1-2@Store", "group": "Content" },
      "backgroundColor": { "dataType": "color", "displayName": "Background Color", "defaultValue": "#FFFFFF", "group": "Colors" },
      "titleColor": { "dataType": "color", "displayName": "Title Color", "defaultValue": "#212529", "group": "Colors" },
      "processColor": { "dataType": "color", "displayName": "Process Color", "defaultValue": "#F8F9FA", "group": "Colors" },
      "processBorderColor": { "dataType": "color", "displayName": "Process Border", "defaultValue": "#E9ECEF", "group": "Colors" },
      "dataStoreColor": { "dataType": "color", "displayName": "Data Store Color", "defaultValue": "#F8F9FA", "group": "Colors" },
      "entityColor": { "dataType": "color", "displayName": "Entity Color", "defaultValue": "#495057", "group": "Colors" },
      "flowColor": { "dataType": "color", "displayName": "Flow Color", "defaultValue": "#6C757D", "group": "Colors" },
      "titleSize": { "dataType": "number", "displayName": "Title Size (px)", "defaultValue": 24, "group": "Typography" },
      "labelSize": { "dataType": "number", "displayName": "Label Size (px)", "defaultValue": 12, "group": "Typography" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'df' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const title = config?.title || "Order Processing System";
  const showFlowLabels = bool(config?.showFlowLabels, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const titleColor = config?.titleColor || "#212529";
  const processColor = config?.processColor || "#F8F9FA";
  const processBorderColor = config?.processBorderColor || "#E9ECEF";
  const dataStoreColor = config?.dataStoreColor || "#F8F9FA";
  const entityColor = config?.entityColor || "#495057";
  const flowColor = config?.flowColor || "#6C757D";
  const titleSize = parseInt(config?.titleSize || '24');
  const labelSize = parseInt(config?.labelSize || '12');

  const HALF_EXTENT = { entity: { hw: 50, hh: 30 }, process: { hw: 50, hh: 50 }, store: { hw: 100, hh: 20 } };

  const defaultNodes = [
    { type: 'entity', label: "Customer", x: 150, y: 130 },
    { type: 'process', label: "Process Order", x: 400, y: 130 },
    { type: 'store', label: "Order Database", x: 400, y: 300 }
  ];
  const defaultFlows = [[0, 1, "Order Data"], [1, 2, "Store"]];

  const parsedNodes = String(config?.nodes || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [typeAndLabel, coords] = entry.split('@');
      const [type, label] = String(typeAndLabel || '').split(':');
      const [x, y] = String(coords || '').split(',').map((n) => parseFloat(n));
      const t = ['entity', 'process', 'store'].includes((type || '').trim()) ? type.trim() : 'process';
      return { type: t, label: (label || `Node ${i + 1}`).trim(), x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y };
    });

  const parsedFlows = String(config?.flows || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry) => {
      const [pair, label] = entry.split('@');
      const [from, to] = pair.split('-').map((n) => parseInt(n));
      return [from, to, (label || '').trim()];
    })
    .filter(([from, to]) => !isNaN(from) && !isNaN(to));

  const nodes = parsedNodes.length > 0 ? parsedNodes : defaultNodes;
  const flows = parsedFlows.length > 0 ? parsedFlows : defaultFlows;
  const arrowId = `${p}-arrow-flow`;

  const renderNode = (node, idx) => {
    const { hw, hh } = HALF_EXTENT[node.type];
    if (node.type === 'entity') {
      return (
        <g key={idx}>
          <rect x={node.x - hw} y={node.y - hh} width={hw * 2} height={hh * 2} fill={entityColor} stroke="none" />
          <text x={node.x} y={node.y + 5} fill="#FFFFFF" fontSize="13px" fontWeight="400" textAnchor="middle">{node.label}</text>
        </g>
      );
    }
    if (node.type === 'store') {
      return (
        <g key={idx}>
          <rect x={node.x - hw} y={node.y - hh} width={hw * 2} height={hh * 2} rx="0" fill={dataStoreColor} stroke={processBorderColor} strokeWidth="2" />
          <line x1={node.x - hw} y1={node.y - hh + 10} x2={node.x + hw} y2={node.y - hh + 10} stroke={processBorderColor} strokeWidth="2" />
          <text x={node.x} y={node.y + hh - 10} fill={titleColor} fontSize="12px" fontWeight="400" textAnchor="middle">{node.label}</text>
        </g>
      );
    }
    return (
      <g key={idx}>
        <circle cx={node.x} cy={node.y} r={hw} fill={processColor} stroke={processBorderColor} strokeWidth="2" />
        <text x={node.x} y={node.y + 5} fill={titleColor} fontSize="12px" fontWeight="400" textAnchor="middle">{node.label}</text>
      </g>
    );
  };

  return (
    <div className={`dataflow-diagram-container ${p}`} style={{ width: '100%', minHeight: '500px', backgroundColor, padding: '32px' }}>
      <style>{`
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <h2 style={{ fontSize: titleSize + 'px', fontWeight: '500', color: titleColor, margin: '0 0 24px 0' }}>{title}</h2>
      <svg width="100%" height="420">
        <defs>
          <marker id={arrowId} markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto">
            <polygon points="0 0, 10 3, 0 6" fill={flowColor} />
          </marker>
        </defs>
        {flows.map(([fromIdx, toIdx, label], idx) => {
          const fromNode = nodes[fromIdx];
          const toNode = nodes[toIdx];
          if (!fromNode || !toNode) return null;
          const fromExt = HALF_EXTENT[fromNode.type];
          const toExt = HALF_EXTENT[toNode.type];
          const dx = toNode.x - fromNode.x;
          const dy = toNode.y - fromNode.y;
          let x1, y1, x2, y2, labelX, labelY;
          if (Math.abs(dx) >= Math.abs(dy)) {
            x1 = fromNode.x + Math.sign(dx || 1) * fromExt.hw;
            x2 = toNode.x - Math.sign(dx || 1) * toExt.hw;
            y1 = fromNode.y;
            y2 = toNode.y;
            labelX = (x1 + x2) / 2;
            labelY = Math.min(y1, y2) - 10;
          } else {
            y1 = fromNode.y + Math.sign(dy || 1) * fromExt.hh;
            y2 = toNode.y - Math.sign(dy || 1) * toExt.hh;
            x1 = fromNode.x;
            x2 = toNode.x;
            labelX = x1 + 20;
            labelY = (y1 + y2) / 2;
          }
          return (
            <g key={idx}>
              <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={flowColor} strokeWidth="2" markerEnd={`url(#${arrowId})`} />
              {showFlowLabels && label && (
                <text x={labelX} y={labelY} fill={flowColor} fontSize={labelSize + 'px'} fontWeight="400" textAnchor="middle">{label}</text>
              )}
            </g>
          );
        })}
        {nodes.map(renderNode)}
      </svg>
    </div>
  );
}

