    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true');

function Component({ config = {} }) {
  const uid = React.useMemo(() => 'cx' + Math.random().toString(36).slice(2, 9), []);
  const p = uid;
  const reduced = React.useMemo(() => {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { return false; }
  }, []);

  const title = config?.title || "Class Hierarchy";
  const showMethods = bool(config?.showMethods, true);
  const showAttributes = bool(config?.showAttributes, true);
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const titleColor = config?.titleColor || "#212529";
  const classColor = config?.classColor || "#F8F9FA";
  const classBorderColor = config?.classBorderColor || "#E9ECEF";
  const relationshipColor = config?.relationshipColor || "#495057";
  const titleSize = parseInt(config?.titleSize || '24');
  const classNameSize = parseInt(config?.classNameSize || '14');
  const memberSize = parseInt(config?.memberSize || '11');
  const classCornerRadius = parseInt(config?.classCornerRadius || '4');

  const defaultClasses = [
    { name: "Animal", x: 250, y: 50, attrs: ["name", "age"], methods: ["eat()", "sleep()"] },
    { name: "Dog", x: 150, y: 240, attrs: ["breed"], methods: ["bark()"] },
    { name: "Cat", x: 350, y: 240, attrs: ["color"], methods: ["meow()"] }
  ];
  const defaultRelationships = [[1, 0], [2, 0]];

  const parsedClasses = String(config?.classes || '')
    .split(';;')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((entry, i) => {
      const [left, coords] = entry.split('@');
      const [name, attrsStr, methodsStr] = String(left || '').split('|');
      const attrs = String(attrsStr || '').split(',').map((a) => a.trim()).filter(Boolean);
      const methods = String(methodsStr || '').split(',').map((m) => m.trim()).filter(Boolean);
      const [x, y] = String(coords || '').split(',').map((n) => parseFloat(n));
      return { name: (name || `Class ${i + 1}`).trim(), attrs, methods, x: isNaN(x) ? 0 : x, y: isNaN(y) ? 0 : y };
    });

  const parsedRelationships = String(config?.relationships || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((pair) => pair.split('-').map((n) => parseInt(n)))
    .filter(([c, par]) => !isNaN(c) && !isNaN(par));

  const classes = parsedClasses.length > 0 ? parsedClasses : defaultClasses;
  const relationships = parsedRelationships.length > 0 ? parsedRelationships : defaultRelationships;

  const classHeight = (cls) => 40 + (showAttributes ? cls.attrs.length * 16 : 0) + (showMethods ? cls.methods.length * 16 : 0) + 10;

  return (
    <div className={`class-diagram-container ${p}`} style={{ width: '100%', minHeight: '500px', backgroundColor, padding: '32px' }}>
      <style>{`
        @media (prefers-reduced-motion: reduce) {
          .${p} * { animation: none !important; transition: none !important; }
        }
      `}</style>
      <h2 style={{ fontSize: titleSize + 'px', fontWeight: '500', color: titleColor, margin: '0 0 24px 0' }}>{title}</h2>
      <svg width="100%" height="420">
        {relationships.map(([childIdx, parentIdx], idx) => {
          const child = classes[childIdx];
          const parent = classes[parentIdx];
          if (!child || !parent) return null;
          const parentHeight = classHeight(parent);
          const x1 = child.x + 75;
          const y1 = child.y;
          const x2 = parent.x + 75;
          const y2base = parent.y + parentHeight;
          return (
            <g key={idx}>
              <line x1={x1} y1={y1} x2={x2} y2={y2base + 10} stroke={relationshipColor} strokeWidth="2" />
              <polygon points={`${x2 - 10},${y2base + 10} ${x2 + 10},${y2base + 10} ${x2},${y2base}`} fill={backgroundColor} stroke={relationshipColor} strokeWidth="2" />
            </g>
          );
        })}
        {classes.map((cls) => {
          const h = classHeight(cls);
          return (
            <g key={cls.name}>
              <rect x={cls.x} y={cls.y} width="150" height={h} rx={classCornerRadius} fill={classColor} stroke={classBorderColor} strokeWidth="2" />
              <rect x={cls.x} y={cls.y} width="150" height="30" rx={classCornerRadius} fill={classBorderColor} />
              <text x={cls.x + 75} y={cls.y + 20} fill={titleColor} fontSize={classNameSize + 'px'} fontWeight="500" textAnchor="middle" dominantBaseline="middle">{cls.name}</text>
              {showAttributes && (
                <g>
                  <line x1={cls.x} y1={cls.y + 30} x2={cls.x + 150} y2={cls.y + 30} stroke={classBorderColor} strokeWidth="1" />
                  {cls.attrs.map((attr, idx) => (
                    <text key={idx} x={cls.x + 10} y={cls.y + 46 + idx * 16} fill={titleColor} fontSize={memberSize + 'px'} fontWeight="400">- {attr}</text>
                  ))}
                </g>
              )}
              {showMethods && (
                <g>
                  <line x1={cls.x} y1={cls.y + 30 + (showAttributes ? cls.attrs.length * 16 : 0)} x2={cls.x + 150} y2={cls.y + 30 + (showAttributes ? cls.attrs.length * 16 : 0)} stroke={classBorderColor} strokeWidth="1" />
                  {cls.methods.map((method, idx) => (
                    <text key={idx} x={cls.x + 10} y={cls.y + 46 + (showAttributes ? cls.attrs.length * 16 : 0) + idx * 16} fill={titleColor} fontSize={memberSize + 'px'} fontWeight="400">+ {method}</text>
                  ))}
                </g>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

